  "task_28457": {"governingAuthority": "Records Retention / Confidentiality", "regulationCode": "IRC § 6001 (retention); partnership / NDA confidentiality clauses; state data-privacy laws", "plainEnglishRule": "Issued financial packages are records that must be retained in their delivered form. They may be distributed only to authorized recipients for that owner or entity.", "auditRisk": "Sending one owner's financials to another is a confidentiality breach (contract damages, loss of client), and overwriting issued reports destroys audit evidence.", "topic": "report_distribution"},
  "task_57292": {"governingAuthority": "US GAAP Presentation / SEC (Non-GAAP)", "regulationCode": "ASC 205 & 220 (financial statement presentation); SEC Regulation G / Item 10(e) of Reg S-K (non-GAAP measures such as NOI, public REITs)", "plainEnglishRule": "Financial reports must present GAAP figures accurately and consistently. Non-GAAP measures like NOI must be defined consistently and reconciled to GAAP when reported publicly. Report filters (book, period, entity) must match the purpose.", "auditRisk": "Reports built on the wrong book, period or entity mislead lenders and investors. Inconsistent non-GAAP definitions draw SEC comment letters for public REITs.", "topic": "fin_report"},
  "task_40265": {"governingAuthority": "US GAAP (Lessor & Revenue Recognition)", "regulationCode": "ASC 842-30 (operating lease income); ASC 606 (non-lease services and fees)", "plainEnglishRule": "Rent is lease income recognized over the lease term; separate services and fees (utilities billed, amenities, bill-backs) follow ASC 606 when they are distinct. Charges must match the lease and addenda.", "auditRisk": "Charges not supported by the lease are unenforceable and invite resident claims. Misclassified revenue components mislead lenders reviewing the T-12.", "topic": "ar_invoice"},
  "task_77265": {"governingAuthority": "Related-Party Rules / Management Agreement", "regulationCode": "ASC 850-10 (related-party disclosures); IRC § 482 (arm's-length); property management agreement", "plainEnglishRule": "Management fees must be calculated exactly as the management agreement defines the fee base and percentage. Fees paid to an affiliate of the owner or manager are related-party transactions that require disclosure.", "auditRisk": "Overcharged fees are a breach of the management agreement (refund claims, termination). Undisclosed related-party fees are a GAAP disclosure deficiency.", "topic": "mgmt_fee"},
  "task_02170": {"governingAuthority": "US GAAP / SOX 404", "regulationCode": "ASC 440-10 (commitments); SOX 404 / COSO Principle 10 (authorization)", "plainEnglishRule": "Purchases must be authorized before the commitment is made, and received goods must be verified before payment (3-way match). Significant unrecorded purchase commitments must be disclosed in the financial statements.", "auditRisk": "Paying without an approved PO or receipt is an authorization-control failure. Undisclosed material commitments are a GAAP disclosure deficiency.", "topic": "purchase_order"},
  "task_11914": {"governingAuthority": "US GAAP / IRS", "regulationCode": "US GAAP accrual basis (FASB Concepts Statement No. 6); ASC 405-10; IRC § 461(h) (economic performance, recurring-item exception)", "plainEnglishRule": "Expenses are recorded in the period the goods or services are received, even if not yet invoiced, and accruals reverse when the invoice arrives. For tax, the deduction generally requires economic performance.", "auditRisk": "Missing or duplicated accruals are the most common cut-off audit adjustment and distort monthly NOI and covenant tests.", "topic": "accrual"},
  "task_53151": {"governingAuthority": "US GAAP / IRS / Consumer Protection", "regulationCode": "ASC 842-30-35-3 (operating lease collectibility); IRC § 166 (bad debts); FDCPA 15 U.S.C. § 1692 & FCRA § 1681s-2 (collections/reporting)", "plainEnglishRule": "When a resident balance is not probable of collection, lease income is limited to cash received, and uncollectible balances are written off per policy after applying deposits. Accounts sent to collection agencies must be accurate, because agencies and credit reporting are regulated.", "auditRisk": "Overstated receivables misstate income. Inaccurate balances reported to collectors or bureaus can create FDCPA/FCRA liability, and inconsistent write-off policy is an audit finding.", "topic": "ar_writeoff"},
