  "task_65595": {"governingAuthority": "Loan & Partnership Agreements", "regulationCode": "Loan agreement approved-budget covenants; partnership / operating agreement major-decision provisions", "plainEnglishRule": "Many loans and partnership agreements require an annual budget approved by the lender or investor, and spending beyond it may need consent. The published budget must be the approved version.", "auditRisk": "Material unapproved spending can breach the operating or loan agreement. Reporting against the wrong budget version misleads investors.", "topic": "budget"},
