  "task_05117": {"governingAuthority": "HUD / Agency Lender Requirements", "regulationCode": "HUD Handbook 4350.1 ch. 4 (Reserve for Replacements); Fannie Mae / Freddie Mac replacement-reserve agreements", "plainEnglishRule": "Replacement reserves are restricted lender escrows: deposits are required monthly and withdrawals need lender approval for eligible capital items, supported by invoices and inspections.", "auditRisk": "Using reserve funds for ineligible items or without approval is a loan default and, for HUD properties, a regulatory violation. Unreconciled reserve balances are an audit finding.", "topic": "reserve"},
  "task_73647": {"governingAuthority": "US GAAP / IRS", "regulationCode": "ASC 340-10 (prepaid expenses); Treas. Reg. § 1.263(a)-4(f) (12-month rule)", "plainEnglishRule": "Costs paid in advance are assets and are expensed over the period they benefit. For tax, prepayments whose benefit does not extend beyond 12 months (or the end of the next tax year) may be deducted when paid.", "auditRisk": "Stale or unamortized prepaid balances overstate assets and understate expense. Book-tax differences must be tracked.", "topic": "prepaid"},
